@media(max-width:700px){.grimoire-reader{width:calc(100vw - 24px);height:calc(100dvh - 30px);border-radius:4px 22px 4px 14px}.reader-heading{padding:18px;gap:10px}.reader-heading h2{font-size:18px;line-height:1.2}.reader-heading small{font-size:8px}.reader-close span{display:none}.reader-body{display:flex;flex-direction:column}.reader-contents{padding:12px 18px;border-right:0;border-bottom:1px solid #aed0e51f;overflow:visible;flex-shrink:0}.reader-emblem,.contents-label,.reader-note{display:none}.reader-contents nav{flex-direction:row;gap:8px}.reader-contents nav button{justify-content:center;flex:1;min-height:37px;padding:8px}.reader-contents nav button>span{font-size:11px}.reader-contents nav strong,.reader-contents nav i{display:none}.reading-stage{flex:1}.reading-page{padding:23px 22px 15px}.reading-page h3{font-size:29px;margin:22px 0 18px}.reading-page>p{font-size:14px;line-height:1.8}.page-overline{font-size:8px}.reading-math{margin:20px 0;font-size:clamp(8px,2.5cqw,13px)}.page-navigation{padding:10px 18px}.reader-footer{padding:13px 18px}.reader-footer>span{font-size:8px;line-height:1.6}.reader-footer button{font-size:11px;padding:11px 13px;gap:18px}.answer-area{margin-top:18px}}
